refentry.refsect1:
&reftitle.description;
&style.oop; intstringmysqli_stmt->insert_id
&style.procedural;
intstringmysqli_stmt_insert_id mysqli_stmtstatement
Devuelve el ID generado por una consulta INSERT o UPDATE en una tabla con una columna que tiene el atributo AUTO_INCREMENT. En el caso de una consulta INSERT de varias filas, devuelve el primer valor generado automáticamente que se insertó con éxito. Si se utiliza LAST_INSERT_ID(expr) para establecer el valor de AUTO_INCREMENT, o en una consulta UPDATE, se devuelve en su lugar el valor de expr.
Devuelve 0 si la consulta no cambió ningún valor AUTO_INCREMENT.

  &reftitle.examples;

   Ejemplo con mysqli_stmt::$insert_id
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$mysqli->query("CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = $mysqli->prepare("INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
$stmt->bind_param('sssi', $name, $countryCode, $district, $population);
$stmt->execute();

printf("El nuevo registro tiene ID %d.\n", $stmt->insert_id);


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$link = mysqli_connect("localhost", "my_user", "my_password", "world");

mysqli_query($link, "CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = mysqli_prepare($link, "INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
mysqli_stmt_bind_param($stmt, 'sssi', $name, $countryCode, $district, $population);
mysqli_stmt_execute($stmt);

printf("El nuevo registro tiene ID %d.\n", mysqli_stmt_insert_id($stmt));


   &examples.outputs;


El nuevo registro tiene ID 1.
